"""Renumber surviving ORD_LINE rows according to legacy semantics."""

from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Coerce LINE_NO for numeric comparison; blank or missing values equal zero."""
    if value == "" or value is None:
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and assign contiguous line numbers per order."""
    surviving = [
        (index, row)
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(
        key=lambda item: (
            str(item[1].get("ORD_ID", "")),
            _numeric_line_no(item[1].get("LINE_NO", "")),
            item[0],
        )
    )

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 0

    for _, row in surviving:
        order = str(row.get("ORD_ID", ""))
        if current_order != order:
            current_order = order
            next_line_no = 1
        else:
            next_line_no += 1

        migrated_row = dict(row)
        migrated_row["LINE_NO"] = next_line_no
        result.append(migrated_row)

    return result
